/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountStickyPhoneScreens, type StickyPhoneScreensOptions } from "../../components/sticky-phone-screens/StickyPhoneScreensEngine.js";
import type { MotionController } from "../../components/sticky-phone-screens/motion-runtime";

export function StickyPhoneScreens({ options, className }: { options?: StickyPhoneScreensOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountStickyPhoneScreens(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="sticky-phone-screens" />;
}

